command:example.dev:code:
$imageConfig = New-AzImageConfig -Location 'West US';
$osDiskVhdUri = "https://contoso.blob.core.windows.net/test/os.vhd"
$dataDiskVhdUri1 = "https://contoso.blob.core.windows.net/test/data1.vhd"
$dataDiskVhdUri2 = "https://contoso.blob.core.windows.net/test/data2.vhd"
Set-AzImageOsDisk -Image $imageConfig -OsType 'Windows' -OsState 'Generalized' -BlobUri $osDiskVhdUri;
Add-AzImageDataDisk -Image $imageConfig -Lun 1 -BlobUri $dataDiskVhdUri1;
Add-AzImageDataDisk -Image $imageConfig -Lun 2 -BlobUri $dataDiskVhdUri2;
New-AzImage -Image $imageConfig -ImageName 'ImageName01' -ResourceGroupName 'ResourceGroup01';

$BatchFile = "runbook.sh" $ResourceGroupName = "HelloRG" $VMScaleSetName = "HelloVmSS" $TypeHandlerVersion = 2.1
#Best Practice for securd paramaters. $protectedSettings = @{ "managedIdentity" = @{ "clientId" = "xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx"}; }
$publicSettings = @{ "fileUris"= (,"https://storage.blob.core.windows.net/itfiles/$($BatchFile)"); "commandToExecute"= "sh $($BatchFile)" }
# Get information about the scale set $vmss = Get-AzVmss ` -ResourceGroupName $ResourceGroupName ` -VMScaleSetName $VMScaleSetName
Add-AzVmssExtension -VirtualMachineScaleSet $vmss ` -Name "CustomScript" ` -Publisher "Microsoft.Azure.Extensions" ` -Type "CustomScript" ` -TypeHandlerVersion $TypeHandlerVersion ` -AutoUpgradeMinorVersion $true ` -Setting $publicSettings ` -ProtectedSetting $protectedSettings
Update-AzVmss ` -ResourceGroupName $ResourceGroupName ` -Name $VMScaleSetName ` -VirtualMachineScaleSet $vmss

